import 'dart:convert';
import 'dart:io';
import 'package:venue_layout_core/venue_layout_core.dart';

void main() {
  File('doc/layout-v2.schema.json').writeAsStringSync(
    '${const JsonEncoder.withIndent('  ').convert(canonicalDocumentSchema())}\n',
  );
  final metadata = canonicalDeclarationMetadata();
  File('doc/layout-v2-metadata.json').writeAsStringSync(
    '${const JsonEncoder.withIndent('  ').convert(metadata)}\n',
  );
  File('doc/layout-v2-metadata.sql').writeAsStringSync(
    '-- Generated by venue_layout_core tool/export_contract.dart. Do not edit.\n'
    'CREATE OR REPLACE FUNCTION public.blueprint_contract_metadata_internal() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public,extensions AS \$metadata\$ SELECT \$json\$${jsonEncode(metadata)}\$json\$::jsonb \$metadata\$;\n'
    'REVOKE ALL ON FUNCTION public.blueprint_contract_metadata_internal() FROM PUBLIC,anon,authenticated,service_role;\n',
  );

  File('doc/layout-text-policy.json').writeAsStringSync(
    '${const JsonEncoder.withIndent('  ').convert(canonicalLayoutTextPolicy)}\n',
  );
  Directory('web/dist').createSync(recursive: true);
  File(
    'web/dist/layout-v2.schema.json',
  ).writeAsBytesSync(File('doc/layout-v2.schema.json').readAsBytesSync());
  File('web/dist/contract.json').writeAsStringSync(
    '${jsonEncode({'protocol': layoutProtocol, 'documentVersion': canonicalDocumentVersion, 'resourceProtocol': canonicalTextResourceProtocol, 'limits': layoutLimits})}\n',
  );
  stdout.writeln('Contract schema and distribution limits generated from core');
}
